    if not isinstance(retired_cpus,list)or any(not isinstance(c,str)for c in retired_cpus)or len(set(retired_cpus))!=len(retired_cpus)or any(c not in expected_cpus for c in retired_cpus)or not isinstance(textfile_path,str)or not textfile_path:raise ValueError('invalid retirement/file inventory')
    if type(now)not in(int,float)or now<0 or now>2**53 or(type(now)is float and not math.isfinite(now))or type(max_age)is not int or not 1<=max_age<=3600:raise ValueError('invalid freshness window')
